// Glue between the runtime and the code generated by XenonRecomp. Compiled
// only in the gow2 executable: it requires the generated ppc_config.h/ppc_context.h
// (build/generated) and the PPCFuncMappings table.
#pragma once

#include <array>
#include <cstdint>
#include <expected>
#include <string>

#include "ppc_config.h"
#include "ppc_context.h"

// Argument registers r3..r10 of a call, in order.
inline std::array<uint64_t, 8> ImportRegs(const PPCContext& ctx) {
  return {ctx.r3.u64, ctx.r4.u64, ctx.r5.u64, ctx.r6.u64, ctx.r7.u64, ctx.r8.u64, ctx.r9.u64, ctx.r10.u64};
}

// Used by the stubs generated by tools/gen_import_stubs.py (with --trace): writes
// "[kernel] Name(r3=0x…, …, r10=0x…)" with LogLine.
void LogImport(const char* name, const PPCContext& ctx);

// First and last+1 of the guest area of the function table read by
// PPC_LOOKUP_FUNC: PPC_IMAGE_BASE + PPC_IMAGE_SIZE, 8 bytes (a host pointer)
// per 4 bytes of code from PPC_CODE_BASE.
inline constexpr uint64_t kFunctionTableBegin = PPC_IMAGE_BASE + PPC_IMAGE_SIZE;
inline constexpr uint64_t kFunctionTableEnd = kFunctionTableBegin + PPC_CODE_SIZE * 2;

struct FunctionTableStats {
  uint32_t installed;  // functions written to the table
  uint32_t skipped;    // guest outside [PPC_CODE_BASE, +PPC_CODE_SIZE)
};

// Writes to base + kFunctionTableBegin the host pointer of every entry of
// PPCFuncMappings, as PPC_LOOKUP_FUNC reads it. Entries outside the code
// section are skipped and written to the log. Error if the table does not fit
// in the guest space.
std::expected<FunctionTableStats, std::string> InstallFunctionTable(uint8_t* base);

// Host function of the function table for a guest address (nullptr if
// outside the code or not mapped).
PPCFunc* LookupFunction(uint8_t* base, uint32_t guest);
